const $=s=>document.querySelector(s),days=['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state;try{state=JSON.parse(localStorage.getItem('studysprint-v1'))}catch{}state ||= {assignments:[],windows:days.map((_,i)=>({start:'17:00',end:i===0||i===6?'17:00':'19:00'}))};let draft=null,proposed=[],view='overview';
const save=()=>{localStorage.setItem('studysprint-v1',JSON.stringify(state));render()};
function notify(s){$('#toast').textContent=s;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),3000)}
const dateKey=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const fmt=d=>new Date(d+'T12:00').toLocaleDateString(undefined,{month:'short',day:'numeric'});
const minutes=t=>Number(t.split(':')[0])*60+Number(t.split(':')[1]);
const time=n=>`${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`;
const weekly=()=>state.windows.reduce((n,w)=>n+Math.max(0,minutes(w.end)-minutes(w.start)),0);
function schedule(a){const result=[],now=new Date(),end=new Date(a.deadline+'T23:59:59'),busy=state.assignments.filter(x=>x.id!==a.id&&x.approved).flatMap(x=>x.sessions.filter(s=>!s.done));let date=new Date(now);date.setHours(0,0,0,0);const jobs=a.milestones.filter(m=>!m.done).map(m=>({...m,left:Math.max(0,Math.round(m.hours*60)-a.sessions.filter(s=>s.done&&s.milestone===m.id).reduce((n,s)=>n+s.end-s.start,0))}));for(let day=0;date<=end&&day<730&&jobs.some(m=>m.left>0);day++,date.setDate(date.getDate()+1)){const key=dateKey(date),w=state.windows[date.getDay()];let start=minutes(w.start),stop=minutes(w.end);if(key===dateKey(now))start=Math.max(start,Math.ceil((now.getHours()*60+now.getMinutes())/15)*15);for(const m of jobs){while(m.left>0&&start<stop){const collision=busy.find(s=>s.date===key&&s.start<=start&&s.end>start);if(collision){start=collision.end;continue}const next=busy.filter(s=>s.date===key&&s.start>start).sort((a,b)=>a.start-b.start)[0];const amount=Math.min(60,m.left,stop-start,next?next.start-start:Infinity);if(amount<=0)break;result.push({id:crypto.randomUUID(),milestone:m.id,title:m.title,date:key,start,end:start+amount,done:false});start+=amount;m.left-=amount}}}const shortfall=jobs.reduce((n,m)=>n+m.left,0);return {sessions:result,shortfall}}
function render(){const all=state.assignments,active=all.filter(a=>a.milestones.some(m=>!m.done)),ms=all.flatMap(a=>a.milestones),sessions=all.filter(a=>a.approved).flatMap(a=>a.sessions.map(s=>({...s,assignment:a}))).filter(s=>!s.done).sort((a,b)=>(a.date+a.start.toString().padStart(4,'0')).localeCompare(b.date+b.start.toString().padStart(4,'0')));$('#nav-count').textContent=active.length;$('#list-count').textContent=all.length;$('#stat-active').textContent=active.length;$('#stat-hours').innerHTML=`${(sessions.reduce((n,s)=>n+s.end-s.start,0)/60).toFixed(1)} <em>hrs</em>`;$('#stat-done').innerHTML=`${ms.filter(m=>m.done).length} <em>/ ${ms.length}</em>`;$('#capacity-label').textContent=`${weekly()/60} hrs / week`;$('#capacity-bar').style.width=`${Math.min(100,weekly()/60/40*100)}%`;let list=all.filter(a=>$('#filter').value==='all'||($('#filter').value==='done'?a.milestones.every(m=>m.done):a.milestones.some(m=>!m.done)));$('#assignments').innerHTML=list.length?list.map(a=>{const done=a.milestones.filter(m=>m.done).length;return `<article class="assignment"><div class="assignment-top"><span class="course">${esc(a.course)}</span><span class="badge ${a.approved?'':'draft'}">${done===a.milestones.length?'Completed':a.approved?'Approved plan':'Draft · review needed'}</span></div><h3>${esc(a.title)}</h3><p>Due ${fmt(a.deadline)} · ${esc(a.priority)} priority · ${done}/${a.milestones.length} milestones</p><div class="progress"><i style="width:${done/a.milestones.length*100}%"></i></div><div class="actions"><button data-review="${a.id}">${a.approved?'Review / replan':'Review draft'} ↗</button><button data-delete="${a.id}">Delete</button></div></article>`}).join(''):`<div class="empty"><span class="empty-icon">▤</span><h3>${all.length?'Nothing in this view':'A fresh start for your next goal'}</h3><p>${all.length?'Try another filter to see your assignments.':'Add an assignment. We’ll help you find the next step.'}</p><button class="text-button" id="empty-add">＋ Add your first assignment</button></div>`;$('#sessions').innerHTML=sessions.length?sessions.slice(0,view==='schedule'?50:4).map(s=>`<div class="session"><small>${fmt(s.date).toUpperCase()} &nbsp; ${time(s.start)}–${time(s.end)}${s.date<dateKey(new Date())?' · MISSED':''}</small><h3>${esc(s.title)}</h3><p>${esc(s.assignment.title)}</p><button data-complete="${s.assignment.id}:${s.id}">✓ Mark complete</button> <button data-review="${s.assignment.id}">Replan</button></div>`).join(''):`<div class="empty"><span class="empty-icon">◷</span><h3>Your time, thoughtfully planned.</h3><p>Approve a plan to see your upcoming study sessions here.</p></div>`;$('#list-title').firstChild.textContent=view==='assignments'?'All assignments ':'Your assignments ';document.querySelector('.hero').hidden=view!=='overview';document.querySelector('.stats').style.display=view==='overview'?'grid':'none';document.querySelector('.content-grid').style.gridTemplateColumns=view==='schedule'?'1fr':'';document.querySelector('.content-grid>.panel').hidden=view==='schedule';document.querySelector('.upcoming').hidden=view==='assignments'}
function openAssignment(){$('#assignment-form').reset();const min=dateKey(new Date());$('#assignment-form [name=deadline]').min=min;$('#assignment-form [name=deadline]').value=dateKey(new Date(Date.now()+7*86400000));$('#editor').showModal()}
['#add','#hero-add'].forEach(s=>$(s).onclick=openAssignment);document.querySelectorAll('.close').forEach(b=>b.onclick=()=>b.closest('dialog').close());document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}));
$('#assignment-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),title=f.get('title').trim(),requirements=f.get('requirements').trim();if(!title||!requirements)return;const text=(title+' '+requirements).toLowerCase(),steps=/code|program|software|app\b/.test(text)?['Review requirements & plan','Implement the solution','Test & fix issues','Final review & submission']:/paper|essay|research|report/.test(text)?['Gather sources & research','Create an outline','Write the first draft','Revise & prepare submission']:['Review requirements','Build understanding','Complete the main deliverable','Review & prepare submission'];draft={id:crypto.randomUUID(),title,course:f.get('course').trim(),deadline:f.get('deadline'),requirements,priority:f.get('priority'),approved:false,milestones:steps.map(t=>({id:crypto.randomUUID(),title:t,hours:Number(f.get('hours'))/4,done:false})),sessions:[]};state.assignments.push(draft);save();$('#editor').close();openReview(draft.id)};
function openReview(id){draft=structuredClone(state.assignments.find(a=>a.id===id));$('#review-title').textContent=draft.title;$('#review-description').textContent=`Due ${fmt(draft.deadline)}. Confirm these suggested steps against your assignment requirements. Adjust estimates before approving.`;$('#milestones').innerHTML=`<details><summary>Assignment requirements</summary><p>${esc(draft.requirements)}</p></details>`+draft.milestones.map((m,i)=>`<div class="milestone-edit"><label>${m.done?'✓ ':''}<input aria-label="Milestone ${i+1} title" data-title="${i}" value="${esc(m.title)}" style="width:100%" ${m.done?'disabled':''}></label><input aria-label="Hours for milestone ${i+1}" type="number" min="0.05" max="200" step="any" data-estimate="${i}" value="${m.hours}" ${m.done?'disabled':''}><span>hrs</span></div>`).join('');validate();$('#review').showModal()}
function validate(){let invalid=false;document.querySelectorAll('[data-estimate]').forEach(input=>{const value=Number(input.value);if(!input.checkValidity()||!Number.isFinite(value)||value<=0)invalid=true;draft.milestones[+input.dataset.estimate].hours=value});document.querySelectorAll('[data-title]').forEach(input=>{if(!input.value.trim())invalid=true;draft.milestones[+input.dataset.title].title=input.value.trim()});const result=invalid?{sessions:[],shortfall:0}:schedule(draft);proposed=result.sessions;$('#validation').className=invalid||result.shortfall?'error':'';$('#validation').textContent=invalid?'Enter a title and a positive estimate for every milestone.':result.shortfall?`This plan needs ${(result.shortfall/60).toFixed(1)} more hours than your available time before the deadline. Edit availability or reduce estimates, then review again.`:`✓ ${proposed.length} study sessions fit before your deadline, with no overlaps. ${draft.approved?'Replanning replaces unfinished sessions.':''}`;$('#approve').disabled=invalid||result.shortfall>0;$('#approve').textContent=draft.approved?'Approve revised plan ✓':'Approve & save plan ✓'}
$('#milestones').oninput=validate;$('#approve').onclick=()=>{validate();if($('#approve').disabled)return;draft.approved=true;draft.sessions=[...draft.sessions.filter(s=>s.done),...proposed];state.assignments[state.assignments.findIndex(a=>a.id===draft.id)]=draft;save();$('#review').close();notify('Plan approved. Your next sprint is ready.')};
document.body.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.id==='empty-add')openAssignment();if(b.dataset.review)openReview(b.dataset.review);if(b.dataset.delete){const a=state.assignments.find(a=>a.id===b.dataset.delete);if(confirm(`Delete “${a.title}” and its plan from this device?`)){state.assignments=state.assignments.filter(item=>item.id!==b.dataset.delete);save();notify('Assignment deleted')}}if(b.dataset.complete){const [aid,sid]=b.dataset.complete.split(':'),a=state.assignments.find(a=>a.id===aid),s=a.sessions.find(s=>s.id===sid);s.done=true;if(a.sessions.filter(x=>x.milestone===s.milestone).every(x=>x.done))a.milestones.find(m=>m.id===s.milestone).done=true;save();notify('One more step forward. Nice work.')}if(b.dataset.view){view=b.dataset.view;document.querySelectorAll('[data-view]').forEach(n=>n.classList.toggle('active',n===b));$('#breadcrumb').textContent=b.querySelector('span').textContent;render()}});
function openHours(){$('#day-inputs').innerHTML=days.map((day,i)=>`<div class="day-row"><label>${day}</label><input aria-label="${day} start" name="start${i}" type="time" value="${state.windows[i].start}" required><input aria-label="${day} end" name="end${i}" type="time" value="${state.windows[i].end}" required></div>`).join('');$('#hours-dialog').showModal()}
$('#availability').onclick=openHours;$('#edit-hours').onclick=openHours;$('#hours-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),windows=days.map((_,i)=>({start:f.get('start'+i),end:f.get('end'+i)}));if(windows.some(w=>w.end<w.start)){notify('End times must follow start times. Use equal times for a day off.');return}state.windows=windows;save();$('#hours-dialog').close();if($('#review').open)validate();notify('Availability updated. Review existing plans to replan them.')};$('#filter').onchange=render;$('#today').textContent=new Date().toLocaleDateString(undefined,{weekday:'short',month:'long',day:'numeric',year:'numeric'});render();
